Section Bundles.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Variables (sp : word) (ds err lo ff fp spa hw dptr : Z).
  Notation spz := (bv_unsigned sp) (only parsing).

  Record dg : Prop := DG {
    g_lo : aceil <= lo /\ lo <= spz - ADS_STACK;
    g_sp : spz mod 16 = 0 /\ spz <= AAPP_HI;
    g_spa : spa mod 32 = 0 /\ spz - 208 <= spa <= spz - 192;
    g_ds : app_obj ds DS_SIZE /\ ds mod 8 = 0 /\ ds + DS_SIZE + 64 <= AAPP_HI /\ ds + DS_SIZE <= aceil;
    g_dsfs : as_FSB H <= ds /\ ds + DS_SIZE <= as_FSB H + AFS_SIZE;
    g_err : - 2 ^ 31 <= err < 0;
    g_hw : hw mod 2 = 1 /\ 0 <= hw < 2 ^ 64 /\ AIMG_TOP <= dptr < 2 ^ 47;
    g_f : aframe_range H 2 ff fp /\ afsb_ok H;
    g_fds : (ff + 256 <= ds \/ ds + DS_SIZE <= ff) /\ (fp + 1 <= ds \/ ds + DS_SIZE <= fp)
            /\ (hull_hi (ds + DS_SIZE) <= ff \/ ff + 256 <= hull_lo ds)
  }.

  Record dsr (m : mem) : Prop := DSR {
    r_16 : rw_cells asegs m (ds + 16) [C8 (Z_to_bv 64 LOC_IMP_A)];
    r_160 : rw_cells asegs m (ds + 160) [C8 (Z_to_bv 64 LOC_IMP_A)];
    r_168 : rw_cells asegs m (ds + 168) [C8 (Z_to_bv 64 0)];
    r_176 : rw_cells asegs m (ds + 176) [C8 (Z_to_bv 64 0)];
    r_184 : rw_cells asegs m (ds + 184) [C8 (Z_to_bv 64 0)];
    r_200 : rw_cells asegs m (ds + 200) [C8 (Z_to_bv 64 0)];
    r_224 : rw_cells asegs m (ds + 224) [C8 (Z_to_bv 64 0)];
    r_320 : rw_cells asegs m (ds + 320) [C8 (Z_to_bv 64 0)];
    r_336 : rw_cells asegs m (ds + 336) [C1 (b8 (bv_unsigned (Z_to_bv 64 0)))];
    r_360 : rw_cells asegs m (ds + 360) [C4 (Z_to_bv 64 (err mod 2 ^ 32))];
    r_368 : rw_cells asegs m (ds + 368) [C1 (b8 (bv_unsigned (Z_to_bv 64 0)))]
  }.

  Definition hdrf (h : nat) (m : mem) : Prop :=
    match h with
    | O => True
    | S O => rw_cells asegs m (ds + 72) [C1 (b8 (bv_unsigned (Z_to_bv 64 44)))]
    | _ => rw_cells asegs m (ds + 72) [C8 (Z_to_bv 64 hw)] /\ rw_cells asegs m (ds + 88) [C8 (Z_to_bv 64 dptr)]
    end.

  Record df (h : nat) (m : mem) : Prop := DF {
    q_ac : ACONST m;
    q_lv : LINV_P5 m;
    q_stk : stk asegs m lo spz;
    q_dsa : addressable m ds DS_SIZE;
    q_dsw : wr_at asegs m ds DS_SIZE;
    q_dsv : shvis m ds (ds + DS_SIZE);
    q_dsr : dsr m;
    q_hdr : hdrf h m;
    q_fw : wr_at asegs m ff 256;
    q_hw : wr_at asegs m (sh ff) 32;
    q_lw : wr_at asegs m fp 1
  }.
End Bundles.

Section DK.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HHbp : asan_rt_hyps_bp H.
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (ds err lo : Z) (ff fp spa hw dptr : Z).
  Hypothesis G : dg H sp ds err lo ff fp spa hw dptr.

  Notation spz := (bv_unsigned sp) (only parsing).
  Notation df := (df sp ds err lo ff fp hw dptr) (only parsing).
  Notation dsr := (dsr ds err) (only parsing).

  Definition WD : list word :=
